{"cards": [{"node_code": "N_0e4a07d47d7b25c0", "definition": "涵盖将产品定量分配至容器或包装单元，以及通过封口技术实现密封保护的专用机械，包括液体、粉体、颗粒及膏体的充填与封口设备。", "boundary": "聚焦于包装流程中“内容物与容器结合”及“密封”的核心环节。边界在于以计量精度、充填方式（如重力、活塞、螺杆）及封口形式（如热封、旋盖、压盖）为分类依据。与“裹包、装盒与装箱机械”的区别在于：本节点侧重容器内部填充及密封，兄弟节点侧重外部包裹及单元化组合。", "includes": ["液体、膏体、粉体及颗粒物料的计量与充填机械", "各类容器（瓶、罐、袋、盒）的封口、旋盖及密封设备"], "excludes": ["产品原料的清洗、破碎、混合等前道加工工序（归入食品加工与饮料机械）", "外包装材料的成型制造（如吹膜、制盒）（归入造纸、印刷与轻工专用机械）"], "sibling_distinctions": [{"other_code": "N_6007da491991328f", "rule": "本节点收录容器内充填及密封设备；兄弟节点收录容器外裹包、装盒及装箱设备。"}, {"other_code": "N_742146729b787b25", "rule": "本节点收录充填封口执行机构；兄弟节点收录包装后的质量检测、标识及整线集成系统。"}], "cross_boundary_rule": "若设备同时包含充填与封口功能（如灌装旋盖一体机），主挂载本节点；若研究重点在于封口后的质量检测或贴标，主挂载“包装检测、贴标与智能包装线”。"}, {"node_code": "N_6007da491991328f", "definition": "涵盖利用包装材料对单个或组合产品进行外部包裹、封装及单元化组合的机械，包括裹包机、装盒机、装箱机及封箱设备。", "boundary": "聚焦于包装流程中“外部包裹”及“物流单元化”环节。边界在于以包裹方式（如收缩、缠绕、折叠）及组合层级（单件、多件、整箱）为分类依据。与“计量、充填、灌装与封口机械”的区别在于：本节点侧重产品外部形态的固定与组合，兄弟节点侧重容器内部填充。", "includes": ["收缩膜、拉伸膜等裹包机械", "自动装盒、装袋及封箱、装箱机械"], "excludes": ["容器内部的充填与封口操作（归入计量、充填、灌装与封口机械）", "包装材料的印刷与成型（归入造纸、印刷与轻工专用机械）"], "sibling_distinctions": [{"other_code": "N_0e4a07d47d7b25c0", "rule": "本节点收录外部裹包及组合设备；兄弟节点收录内部充填及密封设备。"}, {"other_code": "N_742146729b787b25", "rule": "本节点收录裹包装箱执行机构；兄弟节点收录包装后的检测、贴标及智能控制。"}], "cross_boundary_rule": "若研究装盒过程中的视觉定位技术，主挂载本节点；若研究装盒后的标签粘贴或整线调度，主挂载“包装检测、贴标与智能包装线”。"}, {"node_code": "N_742146729b787b25", "definition": "涵盖包装完成后的质量检测、标识施加（贴标、喷码）以及将各环节机械集成为自动化生产线的智能包装系统。", "boundary": "聚焦于包装流程的“后处理”及“系统集成”环节。边界在于以检测技术（视觉、金属探测）、标识技术及产线自动化控制为核心。与“计量、充填、灌装与封口机械”及“裹包、装盒与装箱机械”的区别在于：本节点侧重质量保障、信息标识及整体流程优化，而非单一包装动作的执行。", "includes": ["包装外观、重量、密封性检测及金属/异物探测设备", "自动贴标、喷码、打码及智能包装生产线集成系统"], "excludes": ["包装材料的印刷工艺（归入造纸、印刷与轻工专用机械）", "单纯的机械传动或结构设计理论（归入机械设计与基础零部件）"], "sibling_distinctions": [{"other_code": "N_0e4a07d47d7b25c0", "rule": "本节点收录检测、贴标及整线集成；兄弟节点收录充填封口执行设备。"}, {"other_code": "N_6007da491991328f", "rule": "本节点收录检测、贴标及整线集成；兄弟节点收录裹包装箱执行设备。"}], "cross_boundary_rule": "若研究贴标机的机械结构，主挂载本节点；若研究贴标用的不干胶材料特性，主挂载“造纸、印刷与轻工专用机械”或材料类节点。"}]}
